import{_ as e,o as r,c as a,a3 as d}from"./chunks/framework.CWYzGJW1.js";const p=JSON.parse('{"title":"風險自評","description":"十個問題中, 答「是」越多, 維運前提越穩. 建議門檻為整理者推論 (信心: 低), 用意是找出缺口, 不是評分.","frontmatter":{"description":"十個問題中, 答「是」越多, 維運前提越穩. 建議門檻為整理者推論 (信心: 低), 用意是找出缺口, 不是評分."},"headers":[],"relativePath":"decide/risk-checklist.md","filePath":"decide/risk-checklist.md","lastUpdated":1793060541000}'),o={name:"decide/risk-checklist.md"};function i(n,t,l,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="風險自評" tabindex="-1">風險自評 <a class="header-anchor" href="#風險自評" aria-label="Permalink to &quot;風險自評&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: 決策參考</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-27</li><li>待查證: 十題的選題, 結果門檻與優先順序為整理者設計 (推論); GGUF 官方文件沒有安全性聲明, 第 7 題把 GGUF 與 safetensors 並列屬推論</li></ul></div><p><strong>結論</strong>: 十個問題中, 答「是」越多, 維運前提越穩. 建議門檻為整理者推論 (信心: 低), 用意是找出缺口, 不是評分.</p><h2 id="十個問題" tabindex="-1">十個問題 <a class="header-anchor" href="#十個問題" aria-label="Permalink to &quot;十個問題&quot;">​</a></h2><p>十個問題對應維運中最容易省略的環節: 安全公告, 網路暴露, 版本, 備份, 金鑰, 帳號, 模型來源與工具權限. 題目用到的名詞如下.</p><div class="tip custom-block"><p class="custom-block-title">本頁常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>連接埠 (port)</td><td>服務在網路上等待連線的編號; 開放給誰連, 決定誰能使用這個服務</td></tr><tr><td>映像 (image) 與容器 (container)</td><td>映像是打包好的軟體與執行環境; 容器是由映像啟動的執行個體</td></tr><tr><td>浮動標籤</td><td>例如 latest, 發布者更新時會改指向新內容的映像標籤</td></tr><tr><td>資料卷 (volume)</td><td>容器用來長期保存資料的儲存空間, 刪除容器後資料仍在</td></tr><tr><td>金鑰 (key) 與輪替</td><td>金鑰是服務之間存取用的密碼; 輪替是換上新金鑰, 讓舊金鑰失效</td></tr><tr><td>safetensors 與 GGUF</td><td>兩種常見的模型檔格式, 說明見 <a href="/lanai-handbook/build/m1-inference">M1.5 節</a></td></tr><tr><td>代理 (agent)</td><td>依模型的判斷自行呼叫工具, 連續執行多個步驟的程式</td></tr><tr><td>MCP</td><td>Model Context Protocol, 讓模型連接外部工具的協定</td></tr><tr><td>沙箱 (sandbox)</td><td>隔離的執行環境, 裡面的程式出錯或遭濫用時, 影響不會擴散到主機</td></tr></tbody></table></div><table tabindex="0"><thead><tr><th>#</th><th>問題</th><th>對應章節</th></tr></thead><tbody><tr><td>1</td><td>有具名的人, 每週檢查一次安全公告?</td><td><a href="/lanai-handbook/ops/advisories">O3</a></td></tr><tr><td>2</td><td>所有服務只綁本機或私有網路, 包含容器發布的連接埠?</td><td><a href="/lanai-handbook/build/m2-ui-proxy">M2</a></td></tr><tr><td>3</td><td>每個元件的版本已鎖定並有紀錄, 沒有使用 latest 之類的浮動標籤?</td><td><a href="/lanai-handbook/ops/versioning">O2</a></td></tr><tr><td>4</td><td>每週備份資料卷, 且做過一次還原演練?</td><td><a href="/lanai-handbook/ops/backup">O1</a></td></tr><tr><td>5</td><td>所有金鑰的存放位置已列出, 並確認能在短時間內輪替?</td><td><a href="/lanai-handbook/ops/advisories">O3.3 節</a></td></tr><tr><td>6</td><td>每位使用者有個別帳號, 且已關閉公開註冊?</td><td><a href="/lanai-handbook/know/k6-security">K6.1 節</a></td></tr><tr><td>7</td><td>模型檔來自可追溯的官方來源, 並優先使用 safetensors 或 GGUF?</td><td><a href="/lanai-handbook/build/m1-inference">M1.5 節</a></td></tr><tr><td>8</td><td>檢索用的文件來源只限可信資料夾?</td><td><a href="/lanai-handbook/build/m4-retrieval">M4</a></td></tr><tr><td>9</td><td>若有代理, MCP 或程式碼執行: 已放進沙箱, 且寫入與刪除需人工確認?</td><td><a href="/lanai-handbook/know/k6-security">K6.3 節</a>, <a href="/lanai-handbook/build/m7-tools-sandbox">M7</a></td></tr><tr><td>10</td><td>保留上一版映像與模型, 升級失敗時可回退?</td><td><a href="/lanai-handbook/ops/versioning">O2</a></td></tr></tbody></table><h2 id="結果判讀" tabindex="-1">結果判讀 <a class="header-anchor" href="#結果判讀" aria-label="Permalink to &quot;結果判讀&quot;">​</a></h2><table tabindex="0"><thead><tr><th>答「是」的數量</th><th>建議</th></tr></thead><tbody><tr><td>8 至 10</td><td>可進入 PoC 或小範圍試用; 其餘缺口列入待辦</td></tr><tr><td>5 至 7</td><td>先補齊缺口, 再開放給多人</td></tr><tr><td>4 以下</td><td>僅限單人本機使用, 不對外開放</td></tr></tbody></table><p>答「否」的問題, 在對應章節都有可行做法. 優先補第 2, 3, 4 題, 因為這三項成本低, 且涵蓋 2026 年已知的主要事件起點 (見 <a href="/lanai-handbook/ops/advisories">O3</a>). 第 2, 3 題的依據見參考來源; 第 4 題 (備份) 與事件起點的關聯屬整理者推論 (信心: 低).</p><p>本自評不涉及法規遵循. 該部分請由法務或資安負責人另行檢視.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>十個問題的選題, 結果判讀門檻 (8 至 10, 5 至 7, 4 以下) 與補題順序是整理者設計 (信心: 低, 屬推論), 用意是找出缺口. 第 1, 4, 5, 8, 10 題是維運做法建議, 沒有單一外部來源, 做法與依據見對應章節. 其餘各題可查證的外部事實如下.</p><ul><li><strong>第 2 題, 連接埠</strong>: Docker 文件說明, 發布容器連接埠後, 服務不只對 Docker 主機開放, 也對外部開放; 在發布旗標加上 127.0.0.1 (例如 <code>-p 127.0.0.1:8080:80</code>), 才限制為主機本機存取. 另一份文件說明, 發布連接埠的流量會在進入 ufw 規則之前就轉往其他處理流程, 因此主機上的 ufw 規則未必管得到容器連接埠. <a href="https://docs.docker.com/engine/network/port-publishing/" target="_blank" rel="noreferrer">Docker 文件: Port publishing and mapping</a>, <a href="https://docs.docker.com/engine/network/packet-filtering-firewalls/" target="_blank" rel="noreferrer">Docker 文件: Packet filtering and firewalls</a></li><li><strong>第 3 題, 版本鎖定</strong>: Docker 文件指出映像標籤可變, 發布者可把標籤改指向新映像. LiteLLM 官方事故報告 (2026-10-21) 記載 v1.107.0, latest, main-latest, main-stable 在 11:46 至 14:20 (UTC) 曾遭污染, 並建議固定到 litellm==1.106.2 後重建映像; 報告註明 2026-10-23 的更新修正了部分先前假設, 細節以官方最新版為準. <a href="https://docs.docker.com/build/building/best-practices/" target="_blank" rel="noreferrer">Docker 文件: Building best practices</a>, <a href="https://docs.litellm.ai/blog/security-incident-oct-21-2026" target="_blank" rel="noreferrer">LiteLLM: Security incident Oct 21 2026</a></li><li><strong>第 6 題, 帳號與註冊</strong>: Open WebUI 文件列出 <code>ENABLE_SIGNUP</code> (預設 True, 說明為切換帳號建立) 與 <code>DEFAULT_USER_ROLE</code> (預設 pending). <a href="https://docs.openwebui.com/reference/env-configuration" target="_blank" rel="noreferrer">Open WebUI 文件: Environment Variable Configuration</a></li><li><strong>第 7 題, 模型檔格式</strong>: Hugging Face 文件說明載入 pickle 檔可能執行任意程式碼, 建議不要反序列化不可信來源的資料, 且 Hub 的 Pickle Import 掃描並非萬無一失. Safetensors 文件稱其為以安全方式儲存張量的格式 (相對於 pickle). GGUF 文件只說明它是推論用的二進位格式, 供 llama.cpp, Ollama, LM Studio 等工具使用, 沒有安全性聲明 (2026-10-27 查詢). 題目把 GGUF 與 safetensors 並列, 理由是兩者都不以 pickle 序列化, 載入時不會像 pickle 那樣執行檔案中的程式 (推論, 信心: 中). 但 GGUF 的風險轉移到讀取它的程式: llama.cpp 的安全公告 GHSA-vgg9-87g3-85w8 (CVE-2025-53630) 指出, 經過設計的 GGUF 檔可觸發解析器的整數溢位, 造成記憶體越界讀寫; Cisco Talos 2024 年也通報過同類的 GGUF 解析漏洞 (CVE-2024-21825). 因此 GGUF 檔仍要取自可追溯的來源, 推論引擎也要保持更新. <a href="https://huggingface.co/docs/hub/security-pickle" target="_blank" rel="noreferrer">Hugging Face 文件: Pickle scanning</a>, <a href="https://huggingface.co/docs/safetensors/index" target="_blank" rel="noreferrer">Hugging Face 文件: Safetensors</a>, <a href="https://huggingface.co/docs/hub/gguf" target="_blank" rel="noreferrer">Hugging Face 文件: GGUF</a>, <a href="https://github.com/ggml-org/llama.cpp/security/advisories/GHSA-vgg9-87g3-85w8" target="_blank" rel="noreferrer">llama.cpp 安全公告 GHSA-vgg9-87g3-85w8</a>, <a href="https://talosintelligence.com/vulnerability_reports/TALOS-2024-1912" target="_blank" rel="noreferrer">Cisco Talos: TALOS-2024-1912</a></li><li><strong>第 9 題, 代理的權限與人工確認</strong>: OWASP GenAI LLM01:2025 的緩解方向包含把模型權限限制在最小必要範圍, 以及對特權操作加入人工核准; 同頁指出目前不清楚是否存在萬無一失的提示注入防範方法. <a href="https://genai.owasp.org/llmrisk/llm01-prompt-injection/" target="_blank" rel="noreferrer">OWASP GenAI: LLM01 Prompt Injection</a></li></ul>',14)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
